INSERT INTO destinations (slug, name, is_day_trip) VALUES ('italie', 'Italy (multi-city)', false) ON CONFLICT (slug) DO NOTHING;
INSERT INTO activities (slug, type, destination_id, title, summary, duration_minutes, max_group_size, price_adult_cents, price_child_cents, child_min_age, highlights, included, not_included, important_info, meeting_point, badge, times, is_published)
SELECT v.slug, v.type, d.id, v.title, v.summary, v.mins, v.mx, v.pa, v.pc, v.age::smallint, v.hl, v.inc, v.ninc, v.info, v.meet, v.badge, v.times, true
FROM (VALUES
('colisee-forum-palatin','activity','rome','Colosseum, Roman Forum & Palatine Hill with arena access','Skip-the-line entry, arena access and 2,000 years of history.',180,15,6900,4900,6,ARRAY['Skip-the-line entry','Walk onto the arena floor','Roman Forum and Palatine Hill','Licensed local guide, small group'],ARRAY['Skip-the-line tickets','Licensed guide','Headsets'],ARRAY['Tips','Transport to the meeting point'],'ID required (tickets are named). Comfortable shoes: uneven ground.','Arch of Constantine, Colosseo metro (line B)','Skip-the-line',ARRAY['09:00','11:30','14:00','16:30']),
('vatican-sixtine','activity','rome','Vatican Museums, Sistine Chapel & St Peter''s Basilica','The essential route, without the queue.',210,15,7500,5500,6,ARRAY['Skip-the-line museum entry','Sistine Chapel','Direct access to St Peter''s Basilica'],ARRAY['Skip-the-line tickets','Licensed guide','Headsets'],ARRAY['Dome climb'],'Shoulders and knees must be covered.','Viale Vaticano, in front of the museum entrance','Best seller',ARRAY['08:30','11:00','14:30']),
('food-tour-trastevere','activity','rome','Trastevere food tour: 8 tastings','Supplì, pizza al taglio, cheese and gelato with local artisans.',180,12,7900,5900,4,ARRAY['8 tastings at artisan shops','Rome''s liveliest neighbourhood','Places where Romans actually eat'],ARRAY['8 tastings','1 glass of wine (adults)','Licensed guide'],ARRAY['Extra drinks'],'Tell us about allergies and diets when booking.','Piazza di Santa Maria in Trastevere',NULL,ARRAY['11:00','17:30']),
('rome-by-night','activity','rome','Rome by night: Trevi, Pantheon, Piazza Navona','Baroque squares lit up, without the daytime crowds.',150,20,3900,2500,0,ARRAY['Trevi Fountain without the crowds','The Pantheon lit up','Gelato included'],ARRAY['Licensed guide','1 gelato'],ARRAY['Dinner'],'Stroller-friendly.','Trevi Fountain, Via delle Muratte side',NULL,ARRAY['20:00','21:30']),
('hop-on-hop-off','bus','rome','Hop-on hop-off bus: 24-hour pass','8 stops near the main sights, audio guide in 10 languages.',1440,60,2800,1500,4,ARRAY['Unlimited rides for 24 hours','Open-top double-decker','Audio guide in 10 languages'],ARRAY['24-hour pass','Audio guide (10 languages)','Map of Rome'],ARRAY['Monument entry tickets'],'Buses every 15–20 minutes, 9am to 7pm.','Any stop. Main stop: Termini, Piazza dei Cinquecento','24 h',ARRAY['09:00','12:00','15:00']),
('bus-night','bus','rome','Panoramic night bus tour of Rome','Two hours of illuminated monuments from the top deck.',120,50,3200,1800,4,ARRAY['Colosseum, St Peter''s and Circus Maximus by night','Short photo stops','Live commentary'],ARRAY['Seat on the bus','Live commentary'],ARRAY['Food and drinks'],'Bring a jacket: the top deck is open.','Piazza della Repubblica, in front of the fountain',NULL,ARRAY['20:30','21:30']),
('pompei-naples-journee','circuit','pompei-naples','Pompeii & Naples day trip from Rome','High-speed train, guided Pompeii and pizza in Naples.',720,16,16900,12900,4,ARRAY['Return high-speed train included','Pompeii with an archaeologist guide','Neapolitan pizza lunch'],ARRAY['Return train','Pompeii tickets','Guide','Lunch'],ARRAY['Drinks','Tips'],'Long day with lots of walking.','Roma Termini station, in front of the pharmacy','Day trip',ARRAY['07:30']),
('florence-journee','circuit','florence','Florence day trip from Rome','Duomo, Ponte Vecchio and Michelangelo''s David by high-speed train.',690,16,15900,11900,4,ARRAY['Return high-speed train included','Accademia Gallery (David)','Historic centre on foot'],ARRAY['Return train','Accademia tickets','Guide'],ARRAY['Lunch'],'Wear good walking shoes.','Roma Termini station, in front of the pharmacy','Day trip',ARRAY['07:45']),
('amalfi-journee','circuit','cote-amalfitaine','Amalfi Coast: Positano & Amalfi','Scenic coastal road and a boat ride between the villages.',780,14,18900,14900,4,ARRAY['Positano and Amalfi','Boat trip along the coast','Free time to swim (in season)'],ARRAY['Transport','Boat','Tour leader'],ARRAY['Lunch'],'Boat ride subject to weather.','Piazza della Repubblica','Day trip',ARRAY['07:00']),
('italy-5-days','circuit','italie','Classic Italy in 5 days: Rome, Florence, Venice','Trains, 4-star hotels and guided visits included, one advisor throughout.',7200,16,129000,99000,6,ARRAY['4 nights in 4-star hotels','High-speed trains between cities','Guided tours in each city'],ARRAY['4 nights with breakfast','Trains','Guided tours','Museum tickets'],ARRAY['Flights','Dinners'],'Price per person in a double room.','Your hotel in Rome','5 days',ARRAY['08:00']),
('hotel-trevi','hotel','rome','Boutique hotel near the Trevi Fountain (4★)','Partner hotel 3 minutes'' walk from the fountain, breakfast included.',NULL::int,4,18000,18000,NULL::smallint,ARRAY['Walk to Trevi, the Pantheon and the Spanish Steps','Breakfast included','Airport transfer on request'],ARRAY['Breakfast','Wi-Fi','Air conditioning'],ARRAY['City tax (paid at the hotel)'],'Hotel name and address are sent with the confirmation.','Trevi district, central Rome','4★','{}'::text[]),
('hotel-family','hotel','rome','Family hotel near Termini station (3★)','Family rooms for 4, ideal for day trips by train.',NULL::int,4,12000,12000,NULL::smallint,ARRAY['Family rooms for up to 4 people','5 minutes from Termini station','Breakfast included'],ARRAY['Breakfast','Wi-Fi','Cot on request'],ARRAY['City tax (paid at the hotel)'],'Hotel name and address are sent with the confirmation.','Termini district','3★','{}'::text[]),
('trattoria-trastevere','restaurant','rome','Traditional trattoria dinner in Trastevere','Set Roman menu: cacio e pepe, saltimbocca, tiramisù and wine.',NULL::int,12,4500,4500,NULL::smallint,ARRAY['Table reserved for you','Set 3-course Roman menu','Vegetarian option available'],ARRAY['3-course menu','Water and a quarter litre of wine'],ARRAY['Extra drinks','Tip'],'Tell us about allergies when booking.','Trastevere',NULL,ARRAY['19:00','19:30','20:00','20:30','21:00']),
('rooftop-dinner','restaurant','rome','Rooftop dinner with a view of St Peter''s','Sunset aperitivo and a 4-course dinner facing the dome.',NULL::int,8,8500,8500,NULL::smallint,ARRAY['Window table on request','Sunset aperitivo','4-course menu'],ARRAY['Aperitivo','4-course dinner','Wine pairing'],ARRAY['Tip'],'Smart casual dress code.','Prati district, near the Vatican',NULL,ARRAY['19:30','20:00','20:30','21:00'])
) AS v(slug, type, dest, title, summary, mins, mx, pa, pc, age, hl, inc, ninc, info, meet, badge, times)
JOIN destinations d ON d.slug = v.dest
ON CONFLICT (slug) DO UPDATE SET type = EXCLUDED.type, destination_id = EXCLUDED.destination_id, title = EXCLUDED.title, summary = EXCLUDED.summary, duration_minutes = EXCLUDED.duration_minutes, max_group_size = EXCLUDED.max_group_size, price_adult_cents = EXCLUDED.price_adult_cents, price_child_cents = EXCLUDED.price_child_cents, child_min_age = EXCLUDED.child_min_age, highlights = EXCLUDED.highlights, included = EXCLUDED.included, not_included = EXCLUDED.not_included, important_info = EXCLUDED.important_info, meeting_point = EXCLUDED.meeting_point, badge = EXCLUDED.badge, times = EXCLUDED.times, is_published = true;
UPDATE activities SET is_published = false WHERE slug NOT IN ('colisee-forum-palatin','vatican-sixtine','food-tour-trastevere','rome-by-night','hop-on-hop-off','bus-night','pompei-naples-journee','florence-journee','amalfi-journee','italy-5-days','hotel-trevi','hotel-family','trattoria-trastevere','rooftop-dinner');
INSERT INTO departures (activity_id, starts_at, capacity)
SELECT a.id, (d::date + t::time)::timestamp AT TIME ZONE 'Europe/Rome', a.max_group_size
FROM activities a
CROSS JOIN generate_series(current_date + 1, current_date + 30, interval '1 day') AS d
CROSS JOIN LATERAL unnest(a.times) AS t
WHERE a.is_published AND a.type IN ('activity', 'bus', 'circuit')
ON CONFLICT (activity_id, starts_at, language) DO NOTHING;
